#!/usr/bin/env bash
set -euo pipefail

# Stage the one validated current pre-alpha dataset. tf/ is gitignored so ordinary
# `git add -A` cannot accidentally pick up half-written generated output.
root=$(cd "$(dirname "$0")/.." && pwd)
cd "$root"

version=$(PYTHONPATH=programs python3 -c 'from tlhdig import TF_VERSION; print(TF_VERSION)')
case "${version}" in
  *[!0-9.]*) echo "refusing: TF_VERSION parsed as '${version}', which is not a version"; exit 1;;
esac
dir="tf/${version}"
prov="tf-provenance/${version}"

# Refuse stale or hand-edited generated bytes before staging anything.
python3 programs/check_build_manifest.py || exit 1

# The binary cache TF compiles on load is derived and machine-specific.
find "$dir" "$prov" -type d -name .tf -prune -exec rm -rf {} + 2>/dev/null || true

# GitHub rejects individual files above 100 MB.
oversized=$(find "$dir" "$prov" -type f -size +99M -print 2>/dev/null || true)
if [ -n "$oversized" ]; then
  echo "refusing: generated files exceed GitHub's 100 MB file limit:"
  printf '%s\n' "$oversized"
  exit 1
fi

git add -f "$dir"
if [ -d "$prov" ]; then
  git add -f "$prov"
fi

echo "staged validated current TF ${version}"
git status --short -- "$dir" "$prov"
